  'landing.pricingFreeNowNote': 'The design modules will be free for anyone taking part in Stabileo’s development, and for public universities.',
  'landing.pricingAiNote': 'When it becomes available, Stabileo AI will be a paid feature, priced to cover what it costs to run. For universities and for anyone taking part in its development, we want to offer the option of connecting the language-model API of their choice, so they can try it on their own.',
