  'ex.validation-01': 'Validation 01 · Steel building with slabs',
  'ex.validation-01.desc': 'A three-storey building with steel frames and concrete slabs and core walls meshed in shells, modelled one to one on a published structure, with its numbering and its meshes. The beams sit below the slab mid-plane by an end offset, and the slab pressures are surface loads.',
  'ex.validation-01.purpose': 'Validation / slabs / offsets',
  'pro.tagValidation': 'Validation',
  'ex.validation-06': 'Validation 06 · Plane frame under lateral forces',
  'ex.validation-06.desc': 'A two-bay, five-storey steel frame modelled one to one on a published structure, with its numbering. The seismic forces the source program generated are applied as nodal loads, and the two gravity cases that only built the mass are kept as ordinary cases. The section is given by its properties, with shear deformation.',
  'ex.validation-06.purpose': 'Validation / seismic / shear',
  'ex.validation-02': 'Validation 02 · Light warehouse with trusses',
  'ex.validation-02.desc': 'A steel warehouse with three pitched-truss portal frames, purlins and bracing trusses, modelled one to one on a published structure, with its numbering. Rigid joints, global end offsets and the purlins\' roll angles as in the original; the chord loads are in global and local axes.',
  'ex.validation-02.purpose': 'Validation / trusses / offsets',
  'ex.validation-03': 'Validation 03 · Storehouse with walls',
  'ex.validation-03.desc': 'A storehouse whose two concrete walls, meshed in quadrilateral shells, carry a steel roof of four trusses and five longitudinal channels, modelled one to one on a published structure, with its numbering and its mesh. The angles are given about their principal axes, with each member\'s roll as in the original.',
  'ex.validation-03.purpose': 'Validation / walls / shells',
  'ex.validation-04': 'Validation 04 · Industrial hangar with crane runways',
  'ex.validation-04.desc': 'A steel hangar with roof trusses, a door, annexes, crane runways and a pipe rack, modelled one to one on a published structure, with its numbering: 2482 members, many pinned at their ends, and 22 load cases. The cases are solved linearly and each combination with P-Delta on its factored loads; the original also runs the cases through P-Delta. The original\'s member code check is not reproduced. Combinations with no stable second-order equilibrium are listed without publishing their forces.',
  'ex.validation-04.purpose': 'Validation / P-Delta / releases',
  'ex.validation-05': 'Validation 05 · Guyed tower',
  'ex.validation-05.desc': 'A triangular lattice tower, 57.6 m, held by eighteen guys to three anchors, modelled one to one on a published structure, with its numbering. The guys work in tension only and the combinations are sums of the cases, each with its own active set, as in the original; the wind loads the guys too.',
  'ex.validation-05.purpose': 'Validation / tension only / superposition',
  'ex.validation-07': 'Validation 07 · Building with floor loads',
  'ex.validation-07.desc': 'A four-storey concrete building with an irregular plan, modelled one to one on a published structure, with its numbering. The floor loads are already spread to the beams as trapezoids, cut at each member; each floor is a rigid diaphragm, and self-weight is in the dead-load case.',
  'ex.validation-07.purpose': 'Validation / floors / diaphragm',
