  'flex.scope': 'All eight sheets are compared cell by cell, including their double-reinforcement block, the six characteristic points and the interaction series they plot. Stated differences: circular sections come out ~0.6 % lighter than the workbook; the biaxial surface cut is up to 0.6 % larger mid-quadrant, where the workbook discretizes the compressed zone; on the circular sheet the workbook\'s moment at the axial cap is a straight chord across a gap in its own grid and overstates the curve by 4.4 %, and ours is the curve\'s point; and, once the steel no longer fits in one layer, the bars are stacked here and d is taken to the group’s centroid, which asks for more steel than the workbook, which always assumes a single layer. Under editions later than 2005 results may differ and are not checked against the workbook.',
