  'seismic.blocked.zone0': 'Table 3.1 defines no spectrum for seismic zone 0. Art. 2.5.2 exempts from this code buildings of up to 3 stories or 12 m, and taller ones checked for wind that meet c1, c2 and c3; group Ao is never exempt.',
  'seismic.blocked.siteSF': 'Site class SF requires a site-specific evaluation (art. 2.3.2). Table 3.1 has no row to read.',
  'seismic.assumed.faultProximity': 'The minimum near-fault values printed in Table 3.1 were adopted: Na = {na} and Nv = {nv}. The code gives no fault-distance table to raise them.',
  'seismic.f1.garageSpecial': 'Table 3.1 marks garages (*): they call for a load analysis with every space occupied and the real vehicle weights, not a simultaneity factor.',
  'seismic.derivation.weight': 'W = D + f1·L + f2·S = {dead} + {f1}·{live} + {f2}·{snow} = {total} kN (Eq. 3.15).',
  'seismic.derivation.taOnly': 'Ta = Cr·H^x = {cr}·{h}^{x} = {ta} s (Eq. 6.8, Table 6.2).',
  'seismic.derivation.tComputed': 'The computed period T = {computed} s is used; it is below the Cu·Ta = {cu}·{ta} = {limit} s limit (Eq. 6.7).',
  'seismic.derivation.tCapped': 'The computed period {computed} s exceeds the Eq. 6.7 limit: Cu·Ta = {cu}·{ta} = {limit} s is used instead.',
  'seismic.derivation.cPlateau': 'T = {t} s ≤ T2 = {t2} s, so C = 2.5·Ca·γr/R = {sa}·{gammaR}/{r} = {c} (Eq. 6.3).',
  'seismic.derivation.cSpectrum': 'T = {t} s > T2 = {t2} s, so C = Sa·γr/R = {sa}·{gammaR}/{r} = {c} (Eq. 6.4).',
  'seismic.derivation.cFloorNearFault': 'The Eq. 6.5 floor for zones 3 and 4 governs: C = 0.8·as·Nv/R = 0.8·{as}·{nv}/{r} = {c}.',
  'seismic.derivation.cFloorLowZone': 'The Eq. 6.6 floor for zones 0, 1 and 2 governs: C = 0.11·Ca·γr = 0.11·{ca}·{gammaR} = {c}.',
  'seismic.derivation.dist': 'Vo = {v0} kN distributed over {levels} levels as Wk·hk / ΣWi·hi, with ΣWi·hi = {sumWh} kN·m (Eq. 6.11).',
  'seismic.derivation.distTopHeavy': 'T = {t} s exceeds 2·T2 = {t2} s: 90 % of Vo = {v0} kN is distributed as Wk·hk (ΣWi·hi = {sumWh} kN·m) over {levels} levels and the remaining 10 % is applied entirely at the topmost mass (Eqs. 6.12 and 6.13).',
  'seismic.derivation.distNoMass': 'There is no mass above the reference level: there is nothing to distribute.',
  'seismic.blocked.dynamicRequired': 'Art. 2.7.3 makes the dynamic methods mandatory: T = {t} s exceeds 3·T2 = {limit} s (T2 = {t2} s). The static method does not apply, whatever the height.',
  'seismic.blocked.heightOverTable25': 'Table 2.5 limits the static method to {limit} m for group {group} in zone {zone}; this building is {h} m tall.',
  'seismic.blocked.irregular': 'Table 2.5 admits the static method for buildings regular in plan and in elevation; this one was declared irregular.',
  'seismic.blocked.aoIrregular': 'Table 2.5 admits the static method for group Ao only with line 1a of Tables 2.3 and 2.4 (no irregularity); this building was declared with a medium irregularity.',
  'seismic.assumed.groupCAsB': 'Table 2.5 has no column for group C, so it is read on group B\'s row, which is more demanding than group C\'s risk factor warrants.',
