  'config.tip.showAxes': 'Draws the global X, Y and Z axes at the origin, so you can tell which way the model is oriented.',
  'config.tip.localAxes': 'Shows each member’s own axes — the directions its internal forces are measured in. Useful for reading which way a moment bends the section.',
  'config.tip.localAxesShells': 'The same, for shells (triangles and quads): the directions their bending and membrane results are reported in.',
  'config.tip.showGrid': 'The reference grid behind the model. Turning it off does not change how anything snaps.',
  'config.tip.snapGrid': 'New nodes land on the nearest grid intersection instead of exactly where you clicked.',
  'config.tip.memberDims': 'While you stretch a member in 2D, a tag shows ΔX, ΔZ and its length. It is the same switch as the member tool\'s Dimensions button.',
  'config.tip.gridSize': 'Distance between grid lines, and therefore the step a node snaps to.',
  'config.tip.gridExtent': 'How far the grid reaches from the origin. It is only what you can see — it does not limit where you can draw.',
  'config.tip.smoothOrbit': 'The camera keeps a little momentum when you release the mouse, instead of stopping dead.',
  'config.tip.nodeIds': 'Prints each node’s number next to it — the same numbers the results table uses.',
  'config.tip.elementIds': 'Prints each member’s number on it, so a result in the table can be found in the model.',
  'config.tip.lengths': 'Labels every member with its length. A quick way to catch a node placed one meter off.',
  'config.tip.showLoads': 'Draws the loads on the model. Turning them off leaves the bare structure, which is easier to read while editing geometry.',
  'config.tip.units': 'The units results and details are shown in: diagrams, the results table, the color scale, the status bar and the node and member details. Data tables, tools, load labels and the grid always work in SI (m, kN, MPa).',
  'config.tip.axisConvention': 'How local axes are shown: which side diagrams are drawn on, and which way the Y axis used for qY and Py points. The analysis is always right-handed.',
  'config.tip.momentStyle': 'How a moment is drawn: a double-headed arrow along the axis it turns about, or a curved arrow showing the turn itself.',
  'config.tip.renderMode': 'Members as lines, as solid bars, with their real section extruded along them, or as the concrete is built: members face to face, one solid per beam-column joint and slabs that leave out what the frame occupies. Lines are fastest on a large model.',
  'config.tip.color': 'Colors the members all alike, or by the material or section assigned to each: a quick check that the right one went where you meant.',
  'config.tip.autoSplit': 'Placing a node on an existing member splits it in two at that point, instead of leaving a node sitting on top of an unbroken member.',
  'config.tip.showValues': 'Prints the numbers on the diagram — the peaks and the ends — instead of the shape alone.',
  'config.tip.showReactions': 'Draws the forces the supports give back to the structure. Their sum has to balance the applied load, which makes them the first thing to check.',
  'config.tip.showConstraintForces': 'Draws the forces carried by prescribed displacements and rigid links — the ones that are not reactions at a support.',
  'config.tip.hideLoadsWithDiagram': 'Hides the load arrows while a diagram is on screen, so the two do not overlap on the same members.',
  'config.tip.showPrimarySelector': 'The selector that chooses WHICH result is on screen: simple loads, one load case, a combination, or the envelope.',
  'config.tip.showSecondarySelector': 'The \"Compare\" selector, which overlays a second result on the first for reading them against each other. Needs the primary selector on.',
  'config.tip.drawPositiveTowardLocalAxes': 'Which side a positive value is drawn on: toward the member’s local axes, or on the structural side — sagging down, as it is drawn by hand.',
