  // Step 2
  'dsm.step2.explanation': 'For each member, the <strong>local stiffness matrix</strong> [k] is computed in its own coordinate system.',
  'dsm.step2.whyTruss': 'Truss member: axial force only. In local axes only EA/L appears, on the axial DOFs; the transverse rows are zero and there are no rotations — the member gives the nodes no rotational stiffness at all.',
  'dsm.step2.whyHinge': 'Hinge at end {end}: that end transmits no moment, so its rotation θ{end} is condensed out — its row and column vanish. The member becomes a propped cantilever: 12EI/L³ turns into 3EI/L³, the rotational stiffness at {other} falls from 4EI/L to 3EI/L, and the carry-over 2EI/L disappears.',
  'dsm.step2.whyBothHinged': 'Hinged at both ends: the member transmits no moment at all, and its bending stiffness disappears from [k] — only EA/L is left, exactly as in a truss member. A load along its span still reaches the nodes, as the reactions of a simply supported beam.',
  'dsm.step2.whyReleases3d': "Released here: {list}. Each release condenses that rotation — its row and column vanish, and in that bending plane 12EI/L³ turns into 3EI/L³ (and 4EI/L into 3EI/L at the other end). Releasing torsion removes the whole GJ/L block.",
  'dsm.step2.element': 'Member:',
  'dsm.step2.type': 'Type',
  'dsm.step2.frameNote3d': '12\u00D712 matrix with axial stiffness (EA/L), bending in two planes (EIy, EIz) and torsion (GJ/L).',
  'dsm.step2.trussNote3d': '6\u00D76 matrix (3D truss): only axial stiffness EA/L on the u\u2081,u\u2082 diagonals.',
  'dsm.step2.localMatrix': '[k] \u2014 Local matrix ({rows}\u00D7{cols})',
  // Step 3
  'dsm.step3.explanation': 'The <strong>transformation matrix</strong> [T] rotates member local coordinates to the global system.',
  'dsm.step3.thenGlobal': 'Then the member global stiffness is obtained:',
  'dsm.step3.element': 'Member:',
  'dsm.step3.cosinesNote': 'In 3D, [T] is built with the <strong>direction cosine matrix</strong> R = [e\u2093; e\u1D67; e_z] of the member local system. Size: {rows}\u00D7{cols}',
  'dsm.step3.transformation': '[T] \u2014 Transformation',
  'dsm.step3.globalStiffness': '[K]\u2091 = [T]\u1D40\u00B7[k]\u00B7[T] \u2014 Member global stiffness',
  'dsm.step3.dofMapping': 'Member DOFs:',
  // Step 4
  'dsm.step4.explanation': 'The global stiffness matrix [K] is <strong>assembled</strong> by adding each member\u2019s contributions at the positions of its DOFs.',
  'dsm.step4.highlightElement': 'Highlight member:',
  'dsm.step4.none': 'None',
  'dsm.step4.sizeInfo': 'Dimension: {n} \u00D7 {n} | Members: {nElem}',
  // Step 5
  'dsm.step5.explanation': 'The <strong>load vector</strong> {F} is assembled by combining direct nodal loads, equivalent forces from distributed loads, and other contributions.',
  'dsm.step5.globalVector': 'Global {F} vector',
  'dsm.step5.contributions': 'Detailed contributions',
  'dsm.step5.dof': 'DOF',
  'dsm.step5.value': 'Value',
  'dsm.step5.source': 'Source',
  'dsm.step5.noLoads': 'No loads applied.',
  // Step 6
  'dsm.step6.explanation': 'The system is <strong>partitioned</strong> separating free (f) and restrained (r) DOFs.',
  'dsm.step6.freeDof': 'Free DOFs (f)',
  'dsm.step6.restrainedDof': 'Restrained DOFs (r)',
  'dsm.step6.prescribedDisp': 'prescribed displacements',
  'dsm.step6.prescribedNote': 'Since there are non-zero prescribed displacements, the modified load vector is:',
  'dsm.step6.loadVectorToSolve': '{name} \u2014 Load vector to solve',
  // Step 7
  'dsm.step7.explanation': 'The system of equations is solved for the <strong>free displacements</strong>.',
  'dsm.step7.freeDisp': '{u_f} \u2014 Free displacements ({n} DOF)',
  'dsm.step7.fullVector': 'Full displacement vector (free + restrained):',
  'dsm.step7.fullDisp': '{u} \u2014 Full vector ({n} DOF)',
  // Step 8
  'dsm.step8.explanation': 'The <strong>reactions</strong> at the supports are computed from the obtained displacements.',
  'dsm.step8.reactions': '{R} \u2014 Reactions ({n} restrained DOF)',
  'dsm.step8.dof': 'DOF',
  'dsm.step8.label': 'Label',
  'dsm.step8.reaction': 'Reaction',
  // Step 9
  'dsm.step9.explanation': 'The <strong>internal forces</strong> of each member are computed by transforming global displacements to local coordinates.',
  'dsm.step9.element': 'Member:',
  'dsm.step9.globalDisp': '{u_e} global \u2014 Member displacements',
  'dsm.step9.localDisp': '{u_e} local \u2014 [T]\u00B7{u_e}',
  'dsm.step9.forcesBeforeFEF': '[k]\u00B7{u_local} \u2014 Forces before FEF',
  'dsm.step9.fixedEndForces': '{f_eq} — Equivalent nodal loads of the loads on the member (the fixed-end forces with their sign changed)',
  'dsm.step9.finalForces': '{f} final \u2014 Member internal forces',
  'dsm.step9.drawnAxesNote': 'On this member the method\'s y′ axis (x′ turned 90° counterclockwise) points to the side opposite the drawn z axis. The results table and the diagrams read V and M in the drawn axes, so there they carry the opposite sign to these forces.',
  'dsm.step9.force': 'Force',
