  'dsm.explorer.explanation': 'Explore each member\u2019s matrices: local stiffness <strong>[k]</strong>, transformation <strong>[T]</strong>, and global stiffness <strong>[K]\u2091 = T\u1D40\u00B7k\u00B7T</strong>. The member\u2019s DOFs are highlighted in the global matrix <strong>[K]</strong>.',
