  'matCat.aluminum': 'Aluminum',
  'matCat.coldFormed': "Cold-formed",
  'matCat.stainless': "Stainless",
  'grade.typicalHelp': 'Typical values for this material, not read from the governing standard. Fine for modeling; check them against the standard before a professional verification.',
  'pairing.unusual': '{family} sections are not normally rolled in {grade}. What mills supply:',
  'pairing.stillValid': "The model is valid either way — this is about availability and lead time, not correctness. Ordering another grade means a special production run.",
  'grade.src.iramAcindar': 'IRAM-IAS U 500-503, Argentine mill catalog',
  'grade.src.iramAcindarAngle': "IRAM-IAS U 500-503 — up to 2½\"; larger angles in F-36",
  'grade.src.iramW': "IRAM-IAS U 500-215-6, W series",
  'grade.src.gerdau': "Gerdau, NBR 15980 / ASTM A6 (= AR 350 under NBR 7007)",
  'grade.src.aisc': 'AISC — the standard grade for W shapes',
  'grade.src.iram': 'IRAM-IAS U 500-503 — the next grade up in the same standard',
  'grade.src.en10025': 'EN 10025-2 — stocked across Europe',
  'grade.src.aiscLegacy': 'ASTM A36 — what W shapes were rolled in before A992 (1998)',
  'grade.src.astmA36': 'ASTM A36 — the ordinary grade for channels and angles',
  'grade.src.astmTubeLegacy': 'ASTM A500 Gr.B — long-standing, still widely specified',
  'grade.src.nbr7007': 'NBR 7007 — Brazilian structural steel',
  'grade.src.astmTube': "ASTM A500, structural tube",
  'matCode.label': "Design code",
  'matCode.hint': "Filters to the grades that code normally references. Not a restriction: any grade can be checked to any code.",
  'lore.cirsoc-301-2005.body': "INTI-CIRSOC, Argentina",
  'lore.cirsoc-301-2005.since': "2005; the first edition dates from 1982",
  'lore.cirsoc-301-2005.trivia': 'It is a VERIFICATION code, not an independent one: it adopts AISC 360\'s method almost verbatim and adapts it to Argentine steels and units. That is why an engineer trained on AISC recognizes it immediately — and why the sections it uses are whatever the local mills standardize, IRAM grades alongside ASTM ones.',
  'lore.aisc-360-16.body': "American Institute of Steel Construction",
  'lore.aisc-360-16.since': "2016 edition; the specification line runs back to 1923",
  'lore.aisc-360-16.trivia': "It carries LRFD and ASD side by side in one document, with the same nominal strengths and two different safety formats. That unification happened in 2005; before it the profession was split between two separate specifications and two camps.",
  'lore.aisc-360-22.body': "American Institute of Steel Construction",
  'lore.aisc-360-22.since': "2022 edition",
  'lore.aisc-360-22.trivia': "Added provisions for ductile design and for high-strength steels above 100 ksi, which earlier editions simply did not cover.",
  'lore.en-1993-1-1-2005.body': "CEN, the European Committee for Standardization",
  'lore.en-1993-1-1-2005.since': "2005, replacing the 1992 ENV trial version",
  'lore.en-1993-1-1-2005.trivia': "Each country publishes a National Annex fixing the parameters left open — partial factors, buckling curves, some limits — so “EN 1993” alone does not pin a calculation. The same beam can pass in one country and fail in another, legitimately.",
  'lore.nbr-8800-2008.body': "ABNT, Brazil",
  'lore.nbr-8800-2008.since': "2008, superseding the 1986 edition",
  'lore.nbr-8800-2008.trivia': "The 1986 edition was allowable-stress; 2008 moved to limit states and aligned closely with AISC and Eurocode. NBR 8800:2024 is the current revision.",
  'lore.cirsoc-303-2009.body': "INTI-CIRSOC, Argentina",
  'lore.cirsoc-303-2009.since': "2009",
  'lore.cirsoc-303-2009.trivia': "The cold-formed companion to CIRSOC 301, following AISI's method. Thin walls buckle locally before they yield, which is why they need a separate code rather than a chapter.",
  'lore.aisi-s100-16.body': "American Iron and Steel Institute",
  'lore.aisi-s100-16.since': "2016; the first cold-formed specification is from 1946",
  'lore.aisi-s100-16.trivia': "Introduced the Direct Strength Method as a full alternative to effective widths — instead of reducing each plate element, you compute the whole section's buckling loads and design from those.",
  'lore.en-1993-1-3-2006.body': "CEN",
  'lore.en-1993-1-3-2006.since': "2006",
  'lore.en-1993-1-3-2006.trivia': 'Covers cold-formed members with walls of about 1 mm, and profiled sheeting thinner still.',
  'lore.nbr-14762-2010.body': "ABNT, Brazil",
  'lore.nbr-14762-2010.since': "2010",
  'lore.nbr-14762-2010.trivia': 'Brazil\'s cold-formed code, written around the ZAR galvanized grades of NBR 7008.',
  'lore.en-1999-1-1-2007.body': "CEN",
  'lore.en-1999-1-1-2007.since': "2007",
  'lore.en-1999-1-1-2007.trivia': 'Eurocode 9 is the youngest of the Eurocodes. Aluminum has no yield plateau, so it designs on a 0.2% proof stress, and it must account for the heat-affected zone: welding an aluminum member can halve its strength locally, which no steel code has to say.',
  'lore.adm-2020.body': "The Aluminum Association, United States",
  'lore.adm-2020.since': "2020 edition of the Aluminum Design Manual",
  'lore.adm-2020.trivia': "Uses E = 69,600 MPa and nu = 0.33, against Eurocode 9's 70,000 and 0.30. The same metal, two codes, two moduli — the difference is calibration, not physics.",
  'lore.cirsoc-701-2010.body': "INTI-CIRSOC, Argentina",
  'lore.cirsoc-701-2010.since': "2010",
  'lore.cirsoc-701-2010.trivia': 'Argentina\'s aluminum code, which follows the American ADM tradition rather than the European one.',
  'lore.en-1993-1-4-2006.body': "CEN",
  'lore.en-1993-1-4-2006.since': "2006",
  'lore.en-1993-1-4-2006.trivia': "Stainless has no yield plateau either: its stress-strain curve rounds off gradually, so carbon-steel buckling curves do not apply. That rounding is also why it is more forgiving of local buckling than its strength alone suggests.",
  'lore.aisc-design-guide-27.body': "AISC, United States",
  'lore.aisc-design-guide-27.since': "2013",
  'lore.aisc-design-guide-27.trivia': "A design guide rather than a specification — the United States has no mandatory stainless structural code, so this fills the gap.",
  'lore.cirsoc-201.body': "INTI-CIRSOC, Argentina",
  'lore.cirsoc-201.since': "2005, with a 2025 revision; the line begins in 1982",
  'lore.cirsoc-201.trivia': 'Adapted from ACI 318, which is why it shares its modulus expression E = 4700·√f\'c. Argentine concrete is specified by its characteristic CYLINDER strength, hence H-25 for 25 MPa.',
  'lore.en-1992-1-1.body': "CEN",
  'lore.en-1992-1-1.since': "2004",
  'lore.en-1992-1-1.trivia': "Names concrete by BOTH cylinder and cube strength — C25/30 is one concrete, not a choice, because the cube test reads higher for the same material. Its modulus comes from the MEAN strength, which is why it lands well above ACI's for the same class.",
  'lore.aci-318.body': "American Concrete Institute",
  'lore.aci-318.since': 'current edition 2019; the first is from 1910',
  'lore.aci-318.trivia': "The “318” is just the committee number, and it stuck. Strengths are specified in psi, so the metric equivalents come out at odd values: 4000 psi is 27.6 MPa, not 28.",
  'lore.nbr-6118.body': "ABNT, Brazil",
  'lore.nbr-6118.since': "2014, revised 2023",
  'lore.nbr-6118.trivia': "Its modulus expression scales with the AGGREGATE type — granite, basalt, limestone and sandstone each get their own factor. No other code here does that, and it can move E by 30%.",
  'lore.en-338.body': "CEN",
  'lore.en-338.since': "1995, revised 2016",
  'lore.en-338.trivia': "Strength CLASSES rather than species: C24 means the same properties whether it is Norway spruce or Scots pine. The number is the characteristic bending strength in MPa, C is softwood and D hardwood — which is why a D30 and a C30 bend alike and weigh very differently.",
  'matCode.aboutCode': "About this code",
  'matCode.body': "Written by",
  'matCode.since': "Since",

