  'stress.ccDefaultNote': 'Diamond with e<sub>y</sub> = I<sub>z</sub>/(A\u00B7y<sub>max</sub>) and e<sub>z</sub> = I<sub>y</sub>/(A\u00B7z<sub>max</sub>)',

