  // ─── Tour Steps ───
  'tour.welcomeTitle': 'Welcome to Stabileo',
  'tour.welcomeDesc': 'A free structural analysis program.<br/><br/>In this quick guide you will learn how to build and solve a structure in just a few steps.',
  'tour.modeToggleTitle': 'Three modes, one platform',
  'tour.modeToggleDesc': '<strong>Basic</strong> — 2D & 3D structural analysis with diagrams, stresses and advanced features.<br/><strong>Educational</strong> — Step-by-step exercises to learn structural analysis. <em>(In development)</em><br/><strong>PRO</strong> — Full building analysis with code verification and reports. <em>(In development)</em><br/><br/>This tour will continue in <strong>Basic</strong> mode.',
  'tour.buildOptionsTitle': 'Build your structure',
  'tour.buildOptionsDesc': 'You have three ways to create a model:<br/><br/>&#x2022; <strong>Tools</strong> — Draw nodes, members, supports, and loads like in Paint<br/>&#x2022; <strong>Right side panel</strong> — Enter numerical data directly<br/>&#x2022; <strong>Preloaded examples</strong> — The fastest way to get started<br/><br/>We recommend starting with an example. Let\'s go &#x2192;',
  'tour.examplesTitle': 'Load an example',
  'tour.examplesDesc3D': 'Choose any example to load it instantly.<br/><br/>You can solve all the models that Stabileo 2D has (except trusses).<br/><br/>And there are also <strong>3D Examples</strong> to take advantage of all three dimensions.<br/><br/>Or use the button below to load the recommended one.',
  'tour.examplesDesc2D': 'Choose any example to load it instantly.<br/><br/>Or use the button below to load the recommended one.',
  'tour.examplesBtn3D': '3D Frame',
  'tour.examplesBtn2D': 'Frame Example',
  'tour.manualToolsTitle': 'Manual creation',
  'tour.manualToolsIntro': 'If you prefer to build everything by hand, follow this order:',
  'tour.manualToolsNode': 'Node',
  'tour.manualToolsNodeDesc': 'Place points on the canvas',
  'tour.manualToolsElement': 'Member',
  'tour.manualToolsElementDesc': 'Connect two nodes with a bar',
  'tour.manualToolsSupport': 'Support',
  'tour.manualToolsSupportDesc': 'Restrain the movements of a node',
  'tour.manualToolsLoad': 'Load',
  'tour.manualToolsLoadDesc': 'Apply forces or distributed loads',
  'tour.manualToolsMaterials': 'You can also change <strong>materials</strong> and <strong>sections</strong> from the right side panel.',
  'tour.rightPanelTitle': 'Right side panel',
  'tour.rightPanelDesc': 'Here you can view and edit all the model data:<br/><br/>&#x2022; <strong>Nodes</strong> — Coordinates of each point<br/>&#x2022; <strong>Members</strong> — Bars with their material and section<br/>&#x2022; <strong>Materials</strong> — Properties like E, \u03BD, fy<br/>&#x2022; <strong>Sections</strong> — Pick a commercial profile or create your own custom section<br/>&#x2022; <strong>Supports</strong> — Type and constraints of each support<br/>&#x2022; <strong>Loads</strong> — Forces and distributed loads applied<br/>&#x2022; <strong>Combinations</strong> — Load combinations<br/>&#x2022; <strong>Results</strong> — Appears after solving<br/><br/>Click any field to edit it directly.',
  'tour.solveTitle': 'Solve!',
  'tour.solveDesc': 'When the structure has nodes, members, supports, and at least one load, press <strong>Solve</strong>.<br/><br/>It solves using the <strong>Direct Stiffness Method</strong>.<br/><br/>Use the button below or the one in the sidebar.',
  'tour.solveBtn': 'Solve',
  'tour.resultsTitle': 'Results',
  'tour.resultsDesc': 'Here you can see the analysis results:<br/><br/><strong>Deformed</strong> — Amplified deformed shape of the structure<br/><strong>Moment / Shear / Axial</strong> — Characteristic internal force diagrams for each bar<br/><strong>Axial colors</strong> — Tension (red) vs compression (blue), useful for trusses<br/><strong>Color map</strong> — Heat map based on the intensity of each internal force<br/><br/>Try switching between them to explore.',
  'tour.navigateTitle': 'Navigate the model',
  'tour.navigateDescMobile': 'Use two fingers to <strong>pan</strong> and <strong>zoom</strong>.<br/><br/>In the top right you can tap the <strong>fit</strong> icon to fit the model to your screen.<br/><br/>Press the <strong>\uD83D\uDCCA</strong> button in the top left to open a floating panel with results and diagrams.',
  'tour.navigateDescDesktop': 'With the <strong>Pan</strong> tool, drag the mouse to move around the canvas.<br/>Use the scroll wheel to zoom.<br/><br/>In the top right you can click the <strong>fit</strong> icon to fit the model to your screen.',
  'tour.navigateDesc3DExtra': 'Below that option there are more tools: preset views (top, front, side), perspective/orthographic, clipping plane, and measurement.',
  'tour.queryResultsTitle': 'Query point results',
  'tour.queryResultsDescMobile': 'Activate the <strong>\u2196 Select</strong> tool in <strong>Stress</strong> mode to see the internal forces when tapping a bar.<br/><br/>Or simply move your finger close to a diagram to see the point value.',
  'tour.queryResultsDescDesktop': 'Activate the <strong>Select</strong> tool in <strong>Stress</strong> mode to see the full internal forces when clicking on a bar.<br/><br/>Or simply move the mouse close to a diagram to see the point value.',
  'tour.advancedTitle': 'Advanced Analysis',
  'tour.advancedDesc': 'Tools to go beyond basic bar analysis.<br/><br/>You can click <strong>(?)</strong> to the right of each one to see what it does.',
  'tour.advancedDesc3DExtra': ' As a note, Stabileo 2D currently has many more advanced features.',
  'tour.advancedDescBeta': 'Keep in mind that these features are still in development. Bug reports are appreciated.',
  'tour.peek3dTitle': 'See it in 3D',
  'tour.peek3dDesc': 'The same structure you just analyzed in 2D also works in <strong>3D mode</strong>.<br/><br/>Rotate the model with the mouse (or two fingers on mobile) to explore it from any angle.<br/><br/>All the diagrams, deformed shape, and stress analysis are available in three dimensions too.<br/><br/>When you\'re ready, press Next to return to 2D.',
  'tour.configProjectTitle': 'Settings and Project',
  'tour.configProjectDesc': '<strong>Settings</strong> — Display options: grid, labels, units, and <strong>Live Calculation</strong> (automatically recalculates when editing the structure).<br/><br/><strong>Project</strong> — Save your work, share a link so anyone can see your structure, and export reports (Excel, PDF, PNG, CSV).<br/><br/>The DXF and SVG import/export tools are under development.',
  'tour.feedbackTitle': 'Report bugs or suggest improvements',
  'tour.feedbackDesc': 'Found an error or have an idea?<br/>Press this button to send me a report.<br/><br/>The current state of your model is automatically included so I can reproduce your issue.',
  'tour.goodbyeTitle': 'Thanks for using Stabileo :)',
  'tour.goodbyeDesc': 'I hope it\'s useful for learning and analyzing structures.<br/><br/>If you like it, share the link with colleagues and friends.<br/><br/><em style="color:#4ecdc4; font-style:normal">Bauti</em>',

