  "edu.author.helpDiagEx": 'For example, "What is the moment at midspan?" on member 1, halfway along. The student answers with a number.',
  "edu.author.helpShapeWhat": 'The student picks the SHAPE of each diagram without computing values. It trains them to recognize that a distributed load gives a parabolic moment and linear shear.',
