  'wb.cover.stationsCritical': "critical: quarters, load positions and zero shear",
  'wb.cover.cases': "Load cases",
  'wb.cover.combinations': "Combinations",
  'wb.cover.case': "Case",
  'wb.conv.axes': "Global axes: X and Y horizontal, Z up, right-handed. Displacements and reactions are in global axes.",
  'wb.conv.localAxes': "Member local axes: x from node I to node J; y and z follow the local Y vector and roll angle. The exported roll angle includes both member roll and section rotation, in degrees.",
  'wb.conv.sources': "Result sources: case and combination identify a solved load case or combination. Single (sourceId 0) is a standalone solve, not an individual load case. Envelope exports use source envelope and id 0, with the displayed envelope name. Magnitude is an SRSS or ABS combination: its values are magnitudes without a sign, in no equilibrium, and it is left out of the maxima and the envelope.",
  'wb.conv.selfWeight': "SelfWeight records the direction, factor and scope of each self-weight load. Explicit case loads also apply to an all-loads solve. For legacy projects, separate case and single rows record the self-weight used by each solve; they are alternatives, not additive. This sheet is a record and is not read by the model importer.",
  'wb.conv.units': "SI throughout: m, kN, kN·m; MPa for member stresses and moduli, kN/m² for shell stresses and kN·m/m for shell moments, as the screen shows them; rad for rotations, °C for temperatures. Each header carries its unit in brackets.",
  'wb.conv.displacements': "Displacements: translations ux, uy, uz and rotations about X, Y and Z of each node, as solved.",
  'wb.conv.reactions': "Reactions: the forces and moments the supports exert on the structure, in global axes; they balance the applied loads.",
  'wb.conv.memberForces': "Member forces in local axes, with the solver's sign, which is the one the diagrams on screen show: N positive in tension; Vy, Vz, T, My and Mz as the diagrams draw them.",
  'wb.conv.stations': "Stations: points along each member, x measured from node I. The first and last are the member ends, where the station forces equal the end forces.",
  'wb.conv.deflections': "Deflections: displacement of each station relative to the chord of the member's displaced ends, in local y (v) and z (w), and their resultant.",
  'wb.conv.stresses': "Stresses: largest and smallest normal stress on the section at each station, tension positive. Basis \"geometry\" reads the section's outline; \"bounds\" its bounding rectangle.",
  'wb.conv.shells': 'Shells, at each element\'s center: membrane stresses σxx, σyy, τxy and moments mx, my, mxy in the element\'s local axes (x along its first edge, z normal to it), and for MITC4 quads the transverse shears qx, qy. The global columns turn the same stresses, moments and shears to global axes; a curved quad has none.',
  'wb.conv.shellFaces': "Shell faces: the membrane plus (top, z = +t/2 along the local z) and minus (bottom) 6M/t², each with its principals σ1, σ2, the angle of σ1 from the local x, Von Mises and Tresca (with σ3 = 0). Membrane alone as well. Curved shells have no recovered bending moments or face stresses: those cells are blank and excluded from their maxima. A missing or invalid thickness also leaves the face cells blank.",
  'wb.conv.shellNodes': "Shell nodes: the average, in global components, of the elements around each node. Shell corners: each element's own Von Mises at its corners, as the engine reports it: on the worse face for a triangle, of the membrane for a quad.",
  'wb.conv.envelope': "Envelope: for each node, member end and component, the largest and the smallest value over the combinations (over the cases when there are none), each with the combination that produces it.",
  'wb.conv.maxima': "Maxima: for each component, the largest and smallest value anywhere, where it occurs and under which combination. Member forces are read at the stations.",
  'wb.conv.statics': "Statics: per case and combination, the applied resultant, the reactions' resultant and their sum about the global origin; worstRelative is the largest residual relative to the load.",
  'wb.conv.secondOrder': "Second order: combinations solved with P-Delta. A combination with no second-order equilibrium (the structure buckles below its load) has no result rows and is listed here.",
  'wb.conv.oneWay': "One-way members and lifting supports: the active-set solve of each result, with the members left slack and the supports that lifted.",
  'wb.conv.model': 'Model sheets use the importer\'s sheet names and column keys, so they can be read back; columns the importer does not recognize are skipped. Section properties are the ones the engine was given.',
  'wb.conv.text': "No text cell starts with +, -, = or @, which a spreadsheet would take for a formula: a leading minus is written as the minus sign (−).",
  'wb.conv.precision': 'Numbers are written in full precision. A workbook larger than an xlsx file can hold, or over four million cells, is written as a zip with one CSV per sheet.',
  'wb.zipped': "The workbook is larger than an xlsx file handles well, so it was written as a zip with one CSV per sheet.",
  'wb.button': "Project workbook",
  'wb.tooltip': "Every case and combination, the model and the conventions, in full precision. Above the xlsx row limit, a zip of CSVs.",
  'wb.stations': "Stations",
  'wb.stations5': "5",
  'wb.stations13': "13",
