  'physical.desc.beam.dropped': 'Hangs below the slab. With its top face on the slab\'s, the slab is its flange: designed as a T section, or an L at an edge, with the code\'s flange width.',
  'physical.desc.beam.flat': 'As deep as the slab and wider than deep. Reinforced as a strengthened slab strip; shear is checked over its width.',
  'physical.desc.beam.inverted': 'Rises above the slab, which rests on its bottom face. The slab is on the tension side and it is designed as a rectangular section.',
  'physical.desc.beam.foundation': 'Rests on the ground and spreads the columns\' load along its axis.',
  'physical.desc.beam.tie': 'Ties the footings together so they do not drift apart; it works in tension or compression.',
  'physical.desc.beam.strap': 'Balances a footing on a boundary against the next one and takes the moment of its eccentricity.',
  'physical.desc.beam.edge': 'At the slab\'s edge, with a flange on one side: designed as an L section, and the cantilevering slab hands it torsion.',
  'physical.desc.beam.steel': 'Steel profile, checked to the steel code; the slab rests on its top flange.',
  'physical.desc.beam.timber': 'Sawn or glued-laminated timber, checked as a timber member.',
  'physical.desc.column.concrete': 'Reinforced concrete with one name from bottom to top: on each floor its section and bars, lapped above the joint. The slab rests on its whole section.',
  'physical.desc.column.steel': 'Continuous steel profile, checked for bending with compression to the steel code.',
  'physical.desc.column.composite': 'Steel profile with concrete, encased or inside a tube: a composite section.',
  'physical.desc.column.timber': 'Timber member, checked in compression with its buckling.',
  'physical.desc.slab.solid': 'Constant thickness, reinforced one or two ways by its spans: a bottom mat and top bars over the supports.',
  'physical.desc.slab.joist': 'Joists one way with blocks and a topping; it works along the joists.',
  'physical.desc.slab.waffle': 'Ribs both ways with voids, and solid drop panels around the columns where the shear gathers.',
  'physical.desc.slab.hollowCore': 'Precast planks spanning one way; their capacity comes from the maker.',
  'physical.desc.slab.composite': 'Composite deck with a concrete topping; it works along the deck\'s ribs.',
