  'loads.cirsoc102.unsupported.flexibleBuilding': 'The structure is declared flexible with nothing to take its natural frequency from: pick the modal analysis, a typed frequency or the approximate one of §1.9.3 to compute G_f (§1.9.5). No wind loads are generated.',
