  'loads.cirsoc102.unsupported.torsionalCases': 'Torsional load cases 2 and 4 of §2.4.6 are not implemented: they require applying the eccentricity e = ±0.15 B to the diaphragm, which a frame model cannot receive as a surface pressure. Cases 1 and 3 are generated.',
  'codes.aggregate.assumed': 'The nominal maximum coarse aggregate size is not stated in the project. {mm} mm was adopted, a value common in Argentine practice. This is NOT a regulatory default: CIRSOC 201-2025 sets none. Verify against the actual mix.',
