  'loadPlan.derivation.thermal': "Temperature (T): ΔT = {dt} °C uniform and {grad} °C gradient on {members} members and {shells} shells.",
  'loadPlan.derivation.thermalSenses': "T in both senses (§2.3.4): the ΔT and gradient typed, and their reverse, as two cases taken one at a time in each combination with T.",
  'loadPlan.derivation.soil': "Soil pressure (H): p = K (γ z + q) with K = {k}, γ = {gamma} kN/m³ and q = {q} kN/m² below +{z} m; {total} kN on the vertical shells. K, γ and the level are the project's: CIRSOC 101 does not set them.",
  'loadPlan.derivation.fluid': 'Fluid (F): γ = {gamma} kN/m³ up to +{z} m; pressure on {walls} walls and {bottom} bottom shells.',
  'loadPlan.note.noSoilWalls': "There are no vertical shells below +{z} m: the soil pressure is not applied.",
  'loadPlan.note.noFluidShells': "There are no shells below the fluid level +{z} m: the fluid pressure is not applied.",
  'loadPlan.note.soilSideUnknown': "{n} wall(s) below grade are open on both sides, so which side the soil is on cannot be read from the plan: they take no soil pressure. Give a point on the soil's side.",
  'loadPlan.note.fluidSideUnknown': "{n} wall(s) below the fluid level close no region in, so which side the fluid is on cannot be read from the plan: they take no fluid pressure. Give a point inside the fluid.",
  'loadPlan.note.fluidRegionsAssumed': "No point inside the fluid was given: every region the walls close in below +{z} m was taken as holding the fluid, rooms included. If some are not tanks, give a point inside the fluid.",
  'loadPlan.note.specialEmpty': "{load}: {field} is empty, so this load is not generated.",
  'loadPlan.note.specialPointEmpty': "{load}: the point in plan has an empty coordinate, so it was not used; the side was read off the plan.",
  'loadPlan.derivation.modal': "Modal response spectrum along {dir} (Ch. 7): {modes} modes, {ratio} % of the mass; Vod = {vod} kN by CQC against a static Voe = {voe} kN; factor {scale} (§7.2.5).",
  'loadPlan.derivation.accidentalTorsion': "Accidental torsion (§6.2.4.2): Mta = Fk·eak with eak = {e} % of the plan across the forces, both senses.",
  'loadPlan.derivation.verticalSeismic': "Vertical component (§3.5.2): Ev = (Ca/2)·γr·D = ({ca}/2)·{gr}·D = {kv}·D; each seismic combination goes with D ± {kv}.",
  'loadPlan.note.modalMassShort': "Along {dir} the modes computed add up to {ratio} % of the mass, under the 90 % §7.2.3 asks for.",
  'loadPlan.note.patternsSkipShells': "The alternate arrangements of {symbols} load the members only: the slabs drawn with shells take {symbols} in the full case, and no arrangement loads them. Load their bays by hand where the partial loading matters.",
  'loadPlan.derivation.patterns': "Live load on part of the structure (§4.3.3): {symbols} also loaded only in part ({loads} loads). Each arrangement enters the combinations in place of the full load where that action is the principal one; as a companion it enters whole.",
  'loadPlan.derivation.adjacentSpans': "Loads each side of a support (commentary to §4.3.3): {n} arrangements, the two spans beside a grid line loaded and, beyond them, every other span ({x} lines along X and {y} along Y).",
  'loadPlan.derivation.roofLive': "Roof live load Lr (§4.8.1, {weight} roof, slope {slope} %): between {min} and {max} kN/m² over {n} members, each with R1 from its tributary area.",
  'loadPlan.derivation.roofWeight': "Roof weight (§4.8.1, structure and cladding): {structure} kN/m² of roof members and shells plus {dead} kN/m² of dead load, {total} kN/m²: a {weight} roof.",
  'loadPlan.derivation.roofWeightUnknown': "Roof weight (§4.8.1): part of the roof structure cannot be weighed (a shell with no thickness or a material with no density); taken as a heavy roof, the larger Lr.",
  'loadPlan.derivation.roofDead': "Roof: superimposed dead load {dead} kN/m² on {n} members and shells nothing higher covers.",
  'loadPlan.derivation.roofOccupancy': "Roof used as {occupancy} (§4.8.2): Lo = {lo} kN/m² as live load L, reducible by §4.7; dead {dead} kN/m² on {n} members.",
  'loadPlan.gravity.panels': "Area loads by real tributary area: {members} members take what they collect from the panels they close.",
  'loadPlan.gravity.width': "{n} members close no panel ({sloped} of them sloped) and are loaded with the {width} m tributary width.",
  'loadPlan.gravity.shellLevel': "Level +{z} m: the slab of {n} shells ({area} m²) takes the area load; the beams under it take none from the panels.",
  'loadPlan.gravity.slopedShells': "{n} sloped shells ({area} m² in plan) take the area loads: the dead load per m² of shell, the live loads per m² of plan; the members lying in them take none.",
  'loadPlan.gravity.steepShells': "{n} shells steeper than 30° take no area load (shells {ids}): load them by hand if they are a roof.",
  'loadPlan.gravity.unresolved': '{n} panels whose outline could not be resolved are left unloaded: check for overlapping beams or repeated nodes.',
