  'loadPlan.warning.unmarkedKept': 'Replace keeps {loads} load(s) in the regenerated cases ({cases}) and {combinations} combination(s) using them that the generator did not mark, and ADDS the plan on top. If an older version generated them, the model will hold each of those loads and combinations twice: tick "also remove" below.',
