  'slabColumnJoint.point': 'At level {level} m the slab is joined to each column at one node. On this mesh {share} % of the slab\'s load goes straight into the columns without passing through the beams, a share set by the mesh: it tends to zero as the mesh is refined. A column of finite section takes straight a share set by the stiffness of beams and slab. The split of the slab\'s load between beams and columns is not established, and this member\'s design forces are not presented as the structure\'s. To establish it, tie the slab nodes inside each column\'s section rigidly to the column (on a mesh with nodes on its faces) and solve again.',
