  'detailing.doc.vsDetailing': 'Detailing coordinates the cage: it draws the bars, resolves the clashes and decides what is buildable. This stage ISSUES documents about that cage — drawings, a bending schedule, a report — and records the professional review. Editing steel belongs to Detailing; deciding what leaves the office belongs here.',
