  'detailing.joint.assumedJd': 'Internal elastic lever arm taken as jd = {ratio} d. §15.4.1.1 requires the tension and compression forces generated by flexure without prescribing how to obtain jd; this is a value common for rectangular sections, not a regulatory one.',
  'detailing.joint.unsupported.noIncidentBeams': 'No beams frame into this joint, so the free body cannot be set up.',
  'detailing.joint.unsupported.biaxial': 'Joint with beams in both plan directions. The biaxial check requires setting up the shear in each direction with its own Aj and combining the effects; it is not implemented. Joint shear NOT VERIFIED.',
  'detailing.joint.unsupported.equilibriumResidual': 'The joint free body does not close: an equilibrium residual of {residual} % of the largest contributing force against a limit of {limit} %. Joint shear NOT VERIFIED: a result obtained from a free body that does not close is not a verification.',
