  'footing.general.startersNotModeled': 'Foundation {footing}: column dowels are not drawn yet for this kind of foundation.',
  'footing.assumption.generalPath': 'Foundation {footing} ({kind}): rigid base on soil that takes no tension, checked for every combination with its moments in both directions and turned into the foundation’s axes.',
  'footing.assumption.strap': 'Foundation {footing}: strap beam to {partner} (L = {L} m between columns, e = {e} m along it): it carries M = {M} kN·m and V = {V} kN.',
  'footing.assumption.strapSteel': 'Strap beam from {footing} to {partner} ({b}×{h} cm): it needs As ≥ {as} cm² at the top; its shear, {V} kN, against φVc = {phiVc} kN.',
  'footing.assumption.strapRelief': 'Foundation {footing}: the strap beam from {partner} relieves it by {dR} kN.',
  'footing.assumption.strapLoad': 'Foundation {footing}: the strap beam from {partner} adds {dR} kN to it.',
  'footing.assumption.strapOneWay': 'Foundation {footing}: its strap beam takes the offset and the column\'s moment along it; it is checked with what remains across, under a reaction of {factor}·P.',
  'footing.assumption.strapCentred': 'Foundation {footing}: its strap beams take the offset and the column\'s moments both ways; it is checked centred, under a reaction of {factor}·P.',
  'footing.assumption.balanced': 'Foundation {footing}: its offset across, {e} m, and the wall foot\'s moment across are balanced by the structure it carries; it is checked centred, under its load alone. The wall has to take M = {m} kN·m/m at its foot.',
  'footing.assumption.balancedProp': 'Foundation {footing}: its offset across, {e} m, and the wall foot\'s moment across are balanced by the wall propped by the floor at its head; it is checked centred, under its load alone. The wall takes M = {m} kN·m/m at its foot and the floor a force of {h} kN/m.',
  'footing.assumption.wallSpreads': 'Foundation {footing}: the wall it carries, stiff in its plane, spreads its load along it; it is checked under that load spread over its {B} m, as a wall footing.',
  'footing.ui.balanced': 'Offset balanced by the structure',
  'footing.run.strapNoPartner': 'Foundation {footing}: the foundation its strap beam runs to is not in the model; it is checked as eccentric.',
  'footing.run.strapNotToward': 'Foundation {footing}: its offset does not point to the foundation of its strap beam; it is checked as eccentric.',
  'footing.assumption.pileBearing': 'Pile cap {footing}: the pressure on the record is the most loaded pile’s reaction, in kN, against its allowable capacity.',
  'footing.assumption.wallThickness': 'Strip footing {footing}: the wall states no thickness, 20 cm is used.',
