  // ── Bottom-mat design outcomes ──────────────────────────────────
  'footing.mat.upliftNotEvaluated': 'Direction {axis}: the load eccentricity of {e} m leaves the kern ({limit} m), so the base lifts partially and the linear pressure distribution is no longer valid. No mat is designed for a pressure diagram the soil is not delivering.',
  'footing.mat.geometryNotEvaluated': 'Direction {axis}: no cantilever, no distribution width or no soil pressure to design a mat from.',
  'footing.mat.needsCompressionSteel': 'Direction {axis}: Mu = {Mu} kN·m exceeds what a singly reinforced section {thickness} m thick can carry, so the strength calculation reaches for compression steel. A pad footing is singly reinforced by construction; the answer is a thicker footing, not a top mat resisting the cantilever.',
  'footing.mat.depthBelowMinimum': 'Direction {axis}: the flexural effective depth is {d} m, below the {min} m §13.3.1.2 requires for the bottom reinforcement. The total depth has to be increased.',
  'footing.mat.noFeasibleLayout': 'Direction {axis}: no admissible bar layout exists at Ø{diameter} in the {region} region ({width} m wide) — limit reached: {reason}. The selected diameter was NOT changed and no layout is reported as acceptable.',
  'footing.mat.regionBelowPolicyMinimum': 'Direction {axis}: the {region} region provides {provided} cm², below the {policy} cm² that 0.0018·Ag would ask of that strip on its own. This is a Stabileo conservatism note, NOT a CIRSOC requirement: §7.6.1 imposes its minimum on the direction\'s reinforcement and §13.3.3.3 then distributes the total, and neither clause imposes it again region by region. The design follows the code.',
  'footing.mat.bandOutsideFooting': 'Direction {axis}: §13.3.3.3 (b) puts a {band} m central band on the column axis, and at an offset of {offset} m it does not fit inside the {width} m width. Clipping the band would invent a rule the clause does not state and spreading the steel uniformly would drop the band it requires.',
  'footing.run.columnDoesNotFit': 'Footing {footing}: more than two faces of the critical perimeter fall outside the footing. The column does not fit on this base.',
  'footing.assumption.serviceFromGravityCases': 'Footing {footing}: service reaction for bearing summed at unit factors over {cases}. This project models no service load combination, so the sum is an assumption and not a code-stated combination.',
  'footing.assumption.matCombination': 'Footing {footing}: the mat was designed for combination {combination}, the one that asks for the most steel; a different combination governs the check.',
  'footing.assumption.averageMatDepth': 'Footing {footing}: effective depth taken as {d} m, the AVERAGE mat depth for a Ø{bar} mm two-way mat. The two directions actually sit at different depths.',
  'footing.assumption.flexuralDepths': 'Flexure is designed at each direction\'s own effective depth — {dx} m for the Ø{bx} bars parallel to B and {dy} m for the Ø{by} bars parallel to L. Punching and one-way shear keep the averaged two-layer depth of {punching} m. The difference is intentional, not a disagreement.',
  'footing.assumption.layerEnvelope': 'The two perpendicular mats are stacked, so each direction is either the lower or the upper layer, and no clause decides which. Both depths are known — X would be at {lowx} m as the lower layer or {upx} m as the upper, Y at {lowy} m or {upy} m — and BOTH directions are designed at their upper-layer depth, which is the conservative envelope. §24.3.2 uses cc = {cc} mm, the clear cover of whichever mat ends up closest to the tension face, which is the same number either way. It is reported this way because NEITHER physical arrangement proved code-compliant, so there is no order to design at.',
  'footing.assumption.layerOrderResolved': 'Physical layer order resolved: {order} — the {lower} mat goes in the lower layer ({rationale}). Each direction is designed at its REAL effective depth: dX = {dx} m, dY = {dy} m, with bar centerlines at {ex} mm and {ey} mm above the underside. PR18-A\'s conservative envelope no longer applies; it described a bar sitting one diameter above the real one.',
  'footing.assumption.momentOrientationEnvelope': 'The factored moments ({mb} kN·m about B, {ml} kN·m about L) arrive as reaction moments on global axes, and resolving their sign onto a footing-local axis is not done here. Each is therefore applied in BOTH orientations and the worst critical section governs. That cannot under-state the demand, and it can design a footing for a pressure diagram the real sign would not produce.',
  'footing.assumption.truncatedPerimeter': 'Footing {footing}: {sides} face(s) of the critical perimeter reach the footing edge, so punching was checked as a {position} case.',

  'detailing.footingRun.activeResultSet': 'Active result set (no combination solved)',

  'footing.run.perimeterOppositeFaces': 'Footing {footing}: two OPPOSITE faces of the critical perimeter reach the footing edge. §22.6.5.3 tabulates α_s for interior, edge and corner cases only, and this is none of them — applying a corner α_s to a perimeter of a different shape would be the wrong coefficient, so punching is not checked.',


