  'otherCodes.code.aci318': 'ACI 318',
  'otherCodes.code.ec2': 'EN 1992-1-1',
  'otherCodes.coverage.aisc360': 'Doubly symmetric I and H shapes and tubes: tension, compression (E3, with the E7 reduction of slender elements), flexure with lateral-torsional buckling (F2, Cb = 1, load on the top flange), shear (G2) and interaction (H1). Sections noncompact or slender in flexure and shear with Cv1 < 1 are marked as not evaluated. Each member uses its own stated lengths and K.',
  'otherCodes.coverage.ec3': 'I and H shapes (rolled when picked from a rolled catalog, otherwise welded) and cold-formed tubes: flexural buckling (Table 6.2 curves), lateral-torsional buckling (6.3.2, C1 = 1, load on the top flange), bending, shear and axial force. The class is found without the root radius; class 4 I and RHS use the EN 1993-1-5 effective section, and a class 4 CHS is left out. The 6.3.3 interaction uses the Annex B factors with Cm = 1. Shear with bending and web shear buckling are marked as not evaluated.',
  'otherCodes.coverage.aisiS100': 'Single-sheet lipped C sections: effective width (Appendix 1), compression, tension, flexure with lateral-torsional buckling (F2.1), web shear in the yielding range and interaction. Distortional buckling is not evaluated, so no row reads as a pass; neither is flexural-torsional buckling in compression or weak-axis bending. Z sections are left out.',
  'otherCodes.coverage.aci318': 'Rectangular sections with each member’s stated reinforcement: flexure with axial force (P–M diagram) and shear with stirrups. Beams by region (supports and span) and columns with the bars on both faces. 420 MPa rebar and 2.5 cm cover, as in the CIRSOC design. Members bending about both axes are left out.',
  'otherCodes.coverage.ec2': 'Rectangular beams with the stated reinforcement: flexure (6.1) and shear (6.2) with γc = 1.5, γs = 1.15 and αcc = 1. Flexure does not take the axial force, so columns are left out and a beam with an axial force above 0.1·fcd·Ac is marked as not evaluated. 420 MPa rebar and 2.5 cm cover, as in the CIRSOC design.',
