  'autoLoad.patterns': "Loads on part of the structure (§4.3.3)",
  'autoLoad.patternsHint': "The checkerboards (alternate panels and spans, turned over from one floor to the next) give the larger positive moments; the spans loaded each side of a grid line, and every other one beyond, give the negative ones. Each arrangement is a case that replaces the full load in the combinations where that load is the principal one. The same holds for a reduced Lr (Table 4.1, note n).",
  'autoLoad.roof.title': "Roof",
  'autoLoad.roof.hint': "The roof is what nothing higher covers in plan: the top floor, a lower roof beside a step and sloped roof members. It carries its own dead load and, when it is reached only for maintenance, the roof live load Lr instead of the occupancy's.",
