  'ex.pro-plane-frame-seismic': "Plane frame under static seismic forces",
  'ex.pro-plane-frame-seismic.desc': 'A three-bay, four-story steel frame under the equivalent lateral forces of an earthquake, distributed over the height.',
  'ex.pro-plane-frame-seismic.purpose': "Steel / seismic / drift",
  'ex.pro-plane-frame-seismic.look': 'Solve case E and look at each story\'s drift and the shear in the columns.',
  'ex.rc-qa-diagnostic.look': "Open the combinations and see how each wind and earthquake direction comes in.",
  'ex.3d-building.purpose': "RC / first building / 3D",
  'ex.3d-building.look': "Look at the base reactions and the top floor's displacement under wind and under earthquake.",
  'ex.pro-rc-frame-area-loads': "RC frame with area loads",
  'ex.pro-rc-frame-area-loads.desc': "A four-level concrete frame with its top corner cut away. Floor loads reach the beams by tributary area, and each floor is a rigid diaphragm.",
  'ex.pro-rc-frame-area-loads.purpose': "RC / floor loads / diaphragm",
  'ex.pro-rc-frame-area-loads.look': "Look at the trapezoidal loads on the beams and the columns' torsion under wind along Y.",
  'ex.pro-edificio-7p.look': "Look at the stress contours in slabs and walls, and how the diaphragm shares the wind among the frames.",
  'ex.rc-design-frame': "RC frame for design",
