  'ex.pro-steel-building-slabs.look': "Look at the axial force the beams take from their offset to the slab, and remove the offset on one to compare its moments.",
  'ex.torre-irregular-con-retiros': "Setback tower",
  'ex.torre-irregular-con-retiros.desc': 'An 18-story steel tower with setbacks up its height and outrigger levels.',
  'ex.torre-irregular-con-retiros.purpose': "Steel / irregularity / drift",
  'ex.torre-irregular-con-retiros.look': 'Look at the story drift under wind and how it changes at each setback.',
  'ex.cad-arch-structure-dxf.look': "Read the model's provenance: what came from the drawing and what was assumed.",
  'ex.cad-arch-only-dxf.look': "Compare the proposal with the drawing: every column and beam is listed as an assumption in the provenance.",
  'ex.pro-simple-shed': "Simple shed",
