  'ex.pro-concrete-wall-storehouse.purpose': "Members and shells / walls / roof",
  'ex.pro-concrete-wall-storehouse.look': "Look at the reactions along the base of the walls and the out-of-plane bending at their top.",
  'ex.pro-crane-hangar': "Hangar with an overhead crane",
