  'ex.full-stadium.purpose': "Roof / bowl / cantilever",
  'ex.full-stadium.look': "Look at the roof's radial cantilever and the forces in the ring.",
  'ex.suspension-bridge': "Suspension bridge",
  'ex.suspension-bridge.desc': "A suspension bridge with parabolic cables, vertical hangers and a stiffening truss. The hangers work in tension only. The analysis is linear and the cables are drawn at their unstressed length, so the deflections include the cables' elastic stretch (about 7 m at midspan under dead load) and leave out the stiffening their tension gives: read the forces, not the deflections.",
  'ex.suspension-bridge.purpose': "Cables / deck / long span",
  'ex.suspension-bridge.look': "Look at the tension in the hangers and the force in the main cable under the dead and live deck loads.",
