  // ─── Certified results: combinations, design checks, dynamics, plastic (docs/verification/CERTIFY.md) ───
  'certificate.certifiedAbs': 'Certified: displacement error ≤ {abs}',
  'certificate.envelopeCertified': 'Envelope certified: every value within {abs} of the exact envelope (displacements)',
  'certificate.comboTooltip': 'Rigorous bound, proved in Lean: each load case is certified against the exact solution of the assembled system; a combination\'s bound adds the cases\' bounds times |factor| and the rounding of the combination itself; the envelope lies within the largest combination bound of the exact envelope. The ± next to a member force bounds its error the same way.',
  'certificate.download': 'Download certificate',
  'certificate.bundleTooltip': 'Download this solve\'s certificate bundle (JSON, every number written exactly). Anyone can re-check it independently, without trusting this app, with the Lean checker: lake exe certcheck <file>.',
  'certificate.bundleFailed': 'Could not export the certificate: {reason}',
  'certificate.shellTooltip': 'Certified bound on this resultant\'s error: the exact solution of the assembled system gives a value within ± this of the one shown.',
  'certificate.atPoint': 'exact value within ± {b} (certified)',
  'certificate.modal': 'ω² of {n} modes enclosed (certified)',
  'certificate.modalComplete': 'no mode missed below {f} Hz ({n} modes)',
  'certificate.modalIncomplete': 'completeness not certified: {reason}',
  'certificate.modalMode': 'Mode {i}: f ∈ {range} Hz',
  'certificate.modalAll': 'Certified frequency intervals',
  'certificate.modalTooltip': 'Rigorous enclosures: each computed frequency\'s exact value lies in its interval, and the computed modes are all the modes below the cutoff frequency, none missed (theorems proved in Lean; the change of variables to the stiffness–mass pencil is not formalized).',
  'certificate.pdeltaStable': 'second-order state certified stable',
  'certificate.pdeltaStabilityUnknown': 'stability not certified',
  'certificate.pdeltaTooltip': 'Newton–Kantorovich certificate: the exact P-Δ equilibrium exists, is the only one near the computed one, and differs from the computed displacements by at most this amount (Euclidean norm over all free degrees of freedom). Stable: the exact second-order stiffness is certified positive definite. Not formalized in Lean.',
  'certificate.spectral': 'Certified: Vb ∈ {vb} kN · displacement error ≤ {du} · force error ≤ {df}',
  'certificate.spectralTooltip': 'Rigorous enclosures of the SRSS/CQC response of the exact lowest modes: the exact base shear lies in the interval, and every reported displacement and member force is within the bound of its exact value. Not formalized in Lean.',
  'certificate.harmonicMethod': 'Method: {method}',
  'certificate.harmonicModes': '{n} modes of {dof} DOF',
  'certificate.harmonicTruncation': 'omitted modes carry {pct}% of the static response',
  'certificate.harmonic': 'Certified: peak amplitude ∈ {peak} · reported error ≤ {err}',
  'certificate.harmonicTooltip': 'Rigorous enclosures of the exact steady-state response of the Rayleigh-damped model at the response DOF, at every frequency computed: the exact peak amplitude lies in the interval, and every reported value is within the bound of its exact value, modal truncation included. The phase is not bounded. Not formalized in Lean.',
  'certificate.thStableUpTo': 'Scheme certified stable (Δt ≤ {dt} s)',
  'certificate.thStable': 'Scheme certified stable for any Δt',
  'certificate.thNotStable': 'Stability not certified: {reason}',
  'certificate.thResidual': 'max relative residual of the discrete equations ≤ {r}',
  'certificate.thNoResidual': 'residuals not certified: {reason}',
  'certificate.thTooltip': 'Certifies the discrete scheme: whether it is stable for this model and time step, and how closely the computed trajectory satisfies the scheme\'s equations at every step (certified residuals). It does not bound the error against the continuous motion. Not formalized in Lean.',
  'certificate.plastic': 'λc ∈ {range} (certified)',
  'certificate.plasticOutside': '⚠ The collapse factor λc = {lambda} lies outside the certified enclosure {range} (off by {pct}%): the step-by-step analysis is wrong for this model.',
  'certificate.plasticAxial': 'λc not certified: a bar yielded axially, and the certificate covers bending-only yield.',
  'certificate.plasticTooltip': 'Exact enclosure of the collapse load factor of the rigid–plastic model with bending-only yield: the static theorem gives the lower value, the kinematic theorem (a mechanism) the upper, both checked in exact rational arithmetic.',
  'otherCodes.col.certified': 'Certified',
